    assert WRITTER_TRANSITION_NB_CALLS_FULL * WRITTER_TRANSITION_NB_PARALLEL == WRITTER_TRANSITION_NB_STEPS_FULL

    assert WRITTER_TRANSITION_NB_CALLS <= 255
    assert WRITTER_TRANSITION_NB_CALLS_FULL <= 255


